-- ============================================================
-- znty-rrs 外部导入表 - 演示数据脚本
-- MySQL version: 8.0.33
-- 说明：
--   1. rrs_securityinfo 仅债券大类 + CRMW，不含股票 / 基金 / 主体
--   2. issuer_code 与 ais_inv_analysis.t_inv_company.code、ais_inv_ods.wind_cbondissuer.s_info_compcode 对齐（C10001～C10010）
--   3. 原始单市场样本口径（不含下方新增跨市场记录）：ABS债(abs 资产支持证券) 6 / CRMW 5 / 资产证券化(abs_all) 2 / 私募、永续、次级、担保、含权各 3 / 信用债 5
--      同业存单、大额存单、国债、公司债、中期票据、定向工具、Corp债券、Govt债券、可转债、短期融资券各 1
--      临时代码占位：TMP001.IB=temporary，TMP003.IB=cancelled；TMP002.IB 已更新为 ABN002.IB（abs_all）
--   4. 与 rrs_security_pool_adjust_demo_data.sql 解耦，需单独触发外部导入 Demo
--   5. 标识演示场景（std_clause_flag/std_credit_flag，非系统自动判定规则）：
--      普通信用债、公司债、中票、短融、担保债=1/1；私募债和定向工具=1/0
--      永续、次级、含权及 XYB004 条款不合格样本=0/0；ABS、CRMW、存单、国债、Govt债、可转债=NULL/0
--      XYB005 未判定信用债、Corp债及临时代码=NULL/NULL；不按评级高低判定是否标准
--   exchmarket 与 Wind EXCHMARKET 原值一致；临时代码不写该列，使用登记市场。
--   6. 跨市场补充：XYB001/XYB002/XYB003 各 3 个市场代码（IB/SH/SZ），新增 6 行；
--      同券识别由 Wind S_INFO_ISINCODE 负责，同组主档共用 issuer_code、证券条款
-- ============================================================
USE `znty_rrs`;
SET NAMES utf8mb4;

-- ----------------------------------------------------------------------------
-- 清空业务表
-- ----------------------------------------------------------------------------
-- 清空证券信息表
TRUNCATE TABLE `rrs_securityinfo`;

